WITH exploded AS (SELECT id, customer_id, created_at, element FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) li AS element), valid AS (SELECT *, CASE WHEN element = 'VIP' THEN 1 ELSE 0 END AS is_vip, COALESCE(element, 'DIRECT') AS resolved_element FROM exploded WHERE created_at >= DATE '2025-03-01' AND element = 'BUNDLE'), scored AS (SELECT *, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY is_vip DESC NULLS FIRST) AS is_vip_cume_dist, MIN(is_vip) OVER (PARTITION BY MONTH(created_at)) AS created_at_month_min_is_vip FROM valid), filtered AS (SELECT *, LEAST(is_vip, created_at_month_min_is_vip) AS least_is_vip_created_at_month_min_is_vip FROM scored WHERE element IS NOT NULL) SELECT CASE WHEN created_at_month_min_is_vip >= 70 THEN 'HIGH' ELSE 'LOW' END AS created_at_month_min_is_vip_tier, DATE_TRUNC('DAY', created_at) AS activity_day, MAX(created_at) AS last_created_at, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(element = 'BUNDLE') AS bundle_events, SIZE(COLLECT_SET(element)) AS num_elements FROM filtered GROUP BY GROUPING SETS ((CASE WHEN created_at_month_min_is_vip >= 70 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('DAY', created_at)), (CASE WHEN created_at_month_min_is_vip >= 70 THEN 'HIGH' ELSE 'LOW' END)) HAVING SIZE(COLLECT_SET(element)) > 1;
